#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    /* No argument */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr = NULL;
    long n = strtol(argv[1], &endptr, 10);

    /* Bad input: no conversion at all */
    if (endptr == argv[1]) {
        puts("BAD_INPUT");
        return 0;
    }

    /* Out of allowed range */
    if (n > 1000000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* Numbers smaller than 2 have no prime factors */
    if (n < 2) {
        puts("NONE");
        return 0;
    }

    long remaining = n;
    int first = 1; // flag for printing space

    for (long p = 2; p * p <= remaining; ++p) {
        if (remaining % p == 0) {
            int exp = 0;
            while (remaining % p == 0) {
                remaining /= p;
                ++exp;
            }
            if (!first) putchar(' ');
            printf("%ld^%d", p, exp);
            first = 0;
        }
    }

    if (remaining > 1) {
        if (!first) putchar(' ');
        printf("%ld^1", remaining);
    }

    putchar('\n');
    return 0;
}
